<?php
require_once __DIR__.'/../includes/init.php';require_role('petugas');require_once __DIR__.'/../includes/layout.php';$pdo=db();$q=trim((string)($_GET['q']??''));$type=(string)($_GET['jenis']??'');$p=[];$w=[];if($q!==''){$w[]='(k.plat_nomor LIKE ? OR k.pemilik LIKE ?)';array_push($p,'%'.$q.'%','%'.$q.'%');}if(in_array($type,['motor','mobil','lainnya'],true)){$w[]='k.jenis_kendaraan=?';$p[]=$type;}$ws=$w?' WHERE '.implode(' AND ',$w):'';$s=$pdo->prepare("SELECT k.*,EXISTS(SELECT 1 FROM tb_transaksi t WHERE t.id_kendaraan=k.id_kendaraan AND t.status='masuk') AS sedang_parkir FROM tb_kendaraan k$ws ORDER BY k.plat_nomor");$s->execute($p);$rows=$s->fetchAll();$tariffs=$pdo->query('SELECT jenis_kendaraan,tarif_per_jam FROM tb_tarif ORDER BY jenis_kendaraan')->fetchAll();$areas=$pdo->query('SELECT nama_area,kapasitas,terisi FROM tb_area_parkir ORDER BY nama_area')->fetchAll();render_header('Daftar Kendaraan','kendaraan');?>
<div class="page-intro"><div><h2>Daftar kendaraan</h2><p>Petugas hanya dapat memilih kendaraan yang sudah didaftarkan Admin.</p></div><a class="btn btn-primary" href="<?= h(url('petugas/transaksi-masuk.php')) ?>">＋ Kendaraan masuk</a></div><section class="panel"><div class="table-toolbar"><div><strong><?= count($rows) ?> kendaraan</strong><div class="muted" style="margin-top:4px">Data master bersifat read-only untuk Petugas.</div></div><form method="get" class="toolbar-right"><div class="search-box"><input name="q" value="<?= h($q) ?>" placeholder="Plat nomor atau pemilik"></div><select class="filter-control" name="jenis"><option value="">Semua jenis</option><?php foreach(['motor','mobil','lainnya'] as $t): ?><option value="<?= $t ?>" <?= $type===$t?'selected':'' ?>><?= ucfirst($t) ?></option><?php endforeach; ?></select><button class="btn btn-secondary">Cari</button></form></div><div class="table-wrap"><table><thead><tr><th>Plat nomor</th><th>Jenis</th><th>Warna</th><th>Pemilik</th><th>Tarif/jam</th><th>Status parkir</th></tr></thead><tbody><?php foreach($rows as $r):$price=0;foreach($tariffs as $tr)if($tr['jenis_kendaraan']===$r['jenis_kendaraan'])$price=(float)$tr['tarif_per_jam'];?><tr><td class="td-main"><?= h($r['plat_nomor']) ?></td><td><?= h(ucfirst($r['jenis_kendaraan'])) ?></td><td><?= h($r['warna']) ?></td><td><?= h($r['pemilik']) ?></td><td><?= h(rupiah($price)) ?></td><td><?= $r['sedang_parkir']?status_badge('masuk'):status_badge('keluar') ?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="6"><div class="empty-state">Kendaraan tidak ditemukan.</div></td></tr><?php endif; ?></tbody></table></div></section><div class="content-grid"><section class="panel"><div class="panel-heading"><div><h2>Tarif saat ini</h2><p>Tarif dapat berubah dari akun Admin.</p></div></div><div class="panel-body"><?php foreach($tariffs as $t): ?><div class="area-foot" style="padding:10px 0;border-bottom:1px solid #eef1f6"><span><?= h(ucfirst($t['jenis_kendaraan'])) ?></span><strong><?= h(rupiah($t['tarif_per_jam'])) ?>/jam</strong></div><?php endforeach; ?></div></section><section class="panel"><div class="panel-heading"><div><h2>Ketersediaan area</h2><p>Slot tersedia saat ini.</p></div></div><div class="panel-body"><?php foreach($areas as $a): ?><div class="area-foot" style="padding:10px 0;border-bottom:1px solid #eef1f6"><span><?= h($a['nama_area']) ?></span><strong><?= max(0,(int)$a['kapasitas']-(int)$a['terisi']) ?> / <?= (int)$a['kapasitas'] ?></strong></div><?php endforeach; ?></div></section></div><?php render_footer(); ?>